"""Utilities for finding amounts made from a single coin denomination."""

from math import lcm
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th distinct positive multiple of any denomination in coins.

    An amount may use any number of coins of one denomination, but cannot
    combine denominations. The input list is not modified.

    Args:
        coins: Distinct positive denominations (1-15 values, each 1-25).
        k: One-based position of the desired amount, at most 2 * 10**9.

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # Multiples of a retained denomination already cover any denomination
    # divisible by it. Removing these redundant sets also reduces the work.
    denominations = []
    for coin in sorted(coins):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    if len(denominations) == 1:
        return denominations[0] * k

    upper = denominations[0] * k

    # Inclusion-exclusion: the intersection for a subset of denominations
    # consists of the multiples of their LCM. Combine equal LCMs so each
    # count query needs only one division per distinct, nonzero term.
    coefficients = {}
    for coin in denominations:
        changes = {coin: 1}
        for multiple, coefficient in coefficients.items():
            intersection = lcm(multiple, coin)
            if intersection <= upper:
                changes[intersection] = (
                    changes.get(intersection, 0) - coefficient
                )
        for multiple, change in changes.items():
            coefficient = coefficients.get(multiple, 0) + change
            if coefficient:
                coefficients[multiple] = coefficient
            else:
                coefficients.pop(multiple, None)

    # Find the first bound containing at least k distinct eligible amounts.
    # The k-th multiple of the smallest denomination is a safe upper bound.
    lower = denominations[0]
    while lower < upper:
        middle = (lower + upper) // 2
        count = sum(
            coefficient * (middle // multiple)
            for multiple, coefficient in coefficients.items()
        )
        if count >= k:
            upper = middle
        else:
            lower = middle + 1
    return lower
